CREATE TABLE users (id UUID PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(255) NOT NULL, role VARCHAR(32) NOT NULL CHECK (role IN ('CLAIMANT','CLAIMS_OFFICER','CLAIMS_MANAGER')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE policies (id UUID PRIMARY KEY, policy_number VARCHAR(64) NOT NULL UNIQUE, holder_id UUID NOT NULL REFERENCES users(id), claim_type VARCHAR(32) NOT NULL CHECK (claim_type IN ('MOTOR','PROPERTY')), market VARCHAR(2) NOT NULL CHECK (market IN ('SG','MY','HK')), coverage_limit NUMERIC(15,2) NOT NULL, currency VARCHAR(3) NOT NULL, valid_from DATE NOT NULL, valid_to DATE NOT NULL, status VARCHAR(16) NOT NULL CHECK (status IN ('ACTIVE','EXPIRED','CANCELLED')));
CREATE TABLE claims (id UUID PRIMARY KEY, claim_number VARCHAR(32) NOT NULL UNIQUE, policy_id UUID NOT NULL REFERENCES policies(id), claimant_id UUID NOT NULL REFERENCES users(id), assigned_officer_id UUID REFERENCES users(id), claim_type VARCHAR(32) NOT NULL, market VARCHAR(2) NOT NULL, status VARCHAR(32) NOT NULL, incident_date DATE NOT NULL, description TEXT NOT NULL, incident_details JSONB, claimed_amount NUMERIC(15,2) NOT NULL, reserve_amount NUMERIC(15,2), approved_amount NUMERIC(15,2), rejection_reason TEXT, currency VARCHAR(3) NOT NULL, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE claim_status_history (id UUID PRIMARY KEY, claim_id UUID NOT NULL REFERENCES claims(id), from_status VARCHAR(32), to_status VARCHAR(32) NOT NULL, changed_by UUID REFERENCES users(id), note TEXT, changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE info_requests (id UUID PRIMARY KEY, claim_id UUID NOT NULL REFERENCES claims(id), requested_by UUID NOT NULL REFERENCES users(id), question TEXT NOT NULL, response TEXT, requested_at TIMESTAMPTZ NOT NULL DEFAULT now(), responded_at TIMESTAMPTZ);
